import{_ as a,o as e,c as s,a2 as i}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"Skills","description":"","frontmatter":{},"headers":[],"relativePath":"skills/README.md","filePath":"skills/README.md"}'),r={name:"skills/README.md"};function l(n,t,d,o,h,c){return e(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h1><p>Skills are reusable capabilities for AI agents. Install them with a single command to enhance your agents with access to procedural knowledge.</p><p>Skills are designed to work with a wide range of AI agent frameworks and tools, helping make agents more capable and consistent.</p><p>Each skill encapsulates structured instructions and sometimes executable logic. That means instead of telling an agent how to do something from scratch with prompts, you can install a skill that encodes that knowledge for reuse.</p><h3 id="the-tradeboard-skill-packages" tabindex="-1">The Tradeboard Skill Packages <a class="header-anchor" href="#the-tradeboard-skill-packages" aria-label="Permalink to &quot;The Tradeboard Skill Packages&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Package</th><th>Covers</th><th>Repository</th></tr></thead><tbody><tr><td><a href="./execution.html">Execution</a></td><td>The full Tradeboard Python SDK surface: orders, execution algorithms, scanners, visualization, WebSocket streaming, and Telegram/WhatsApp alerts</td><td><a href="https://github.com/wesoftcorp/tradeboard-skills" target="_blank" rel="noreferrer">tradeboard-skills</a></td></tr><tr><td><a href="./indicators.html">Indicators</a></td><td>The <code>tradeboard.ta</code> library, Plotly charts, dashboards, and scanners</td><td><a href="https://github.com/wesoftcorp/tradeboard-indicator-skills" target="_blank" rel="noreferrer">tradeboard-indicator-skills</a></td></tr><tr><td><a href="./backtesting.html">Backtesting</a></td><td>VectorBT backtests for Indian, US, and crypto markets, with realistic cost models and QuantStats tearsheets</td><td><a href="https://github.com/marketcalls/vectorbt-backtesting-skills" target="_blank" rel="noreferrer">vectorbt-backtesting-skills</a></td></tr></tbody></table><p>Two related packages are not documented here but exist in the ecosystem: <code>tradeboard-execution-skills</code>, which pairs a backtest and a live implementation of the same strategy, and <code>tradeboard-claude-plugin</code>, a Claude Code plugin marketplace.</p><h3 id="installing" tabindex="-1">Installing <a class="header-anchor" href="#installing" aria-label="Permalink to &quot;Installing&quot;">​</a></h3><p>All packages install through <a href="https://github.com/vercel-labs/skills" target="_blank" rel="noreferrer">skills.sh</a>, which detects the agents on your machine and writes each skill into the directory that agent reads:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> marketcalls/tradeboard-skills</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> marketcalls/tradeboard-indicator-skills</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> marketcalls/vectorbt-backtesting-skills</span></span></code></pre></div><p>Add <code>-g</code> to install globally rather than into the current project, and <code>-l</code> to list the skills a repository contains before installing.</p><h3 id="skills-compared-to-mcp" tabindex="-1">Skills Compared to MCP <a class="header-anchor" href="#skills-compared-to-mcp" aria-label="Permalink to &quot;Skills Compared to MCP&quot;">​</a></h3><p>Both let an AI agent work with Tradeboard, and they solve different halves of the problem.</p><table tabindex="0"><thead><tr><th></th><th>Skills</th><th><a href="./../mcp/README.html">MCP</a></th></tr></thead><tbody><tr><td>What it gives the agent</td><td>Knowledge: how to structure a strategy, which endpoint to call, how to read the response</td><td>Capability: 49 callable tools that reach a running Tradeboard instance</td></tr><tr><td>Where the work happens</td><td>The agent writes Python that you run</td><td>The agent calls Tradeboard directly</td></tr><tr><td>Needs Tradeboard running</td><td>Only when the generated code runs</td><td>Yes, for every call</td></tr><tr><td>Good for</td><td>Building and backtesting strategies, dashboards, and scanners</td><td>Asking about positions, quotes, and Greeks, and placing orders conversationally</td></tr></tbody></table><p>They compose. A common setup is Skills installed for writing strategy code and MCP connected for inspecting the account while you write it.</p><h3 id="safety" tabindex="-1">Safety <a class="header-anchor" href="#safety" aria-label="Permalink to &quot;Safety&quot;">​</a></h3><p>Generated code places real orders when you run it against a live Tradeboard instance. Run it in Analyzer mode first, read what it does before you run it, and treat a skill&#39;s output as a draft you own rather than a finished system. See <a href="./../responsibilities.html">Responsibilities</a>.</p>`,17)])])}const g=a(r,[["render",l]]);export{p as __pageData,g as default};
